def sliding_window_average(lst, k):
    if not isinstance(k, int) or k <= 0 or k > len(lst):
        return []
    n = len(lst)
    running_sum = sum(lst[:k])
    result = [round(running_sum / k, 4)]
    for i in range(1, n - k + 1):
        running_sum += lst[i + k - 1] - lst[i - 1]
        result.append(round(running_sum / k, 4))
    return result

def expand_repeated_chars(s):
