        return ''
    ch = s[0]
    i = 1
    while i < len(s) and s[i].isdigit():
        i += 1
    count = int(s[1:i])
    return ch * count + expand_repeated_chars(s[i:])

def toggle_sentence_case(s):
    result_chars = []
    seen_alpha = False
    for ch in s:
        if ch.isalpha():
            if not seen_alpha:
                result_chars.append(ch.lower())
                seen_alpha = True
            else:
                result_chars.append(ch.upper())
        else:
            result_chars.append(ch)
    if not seen_alpha:
        return ''.join(result_chars).lower()
    return ''.join(result_chars)

