def get_nested(d, path, sep, default):
    parts = path.split(sep)
    def walk(node, remaining):
        if not remaining:
            return node
        key, rest = remaining[0], remaining[1:]
        if isinstance(node, dict) and key in node:
            return walk(node[key], rest)
        return default
    return walk(d, parts)

def is_valid_temperature_reading(s):
    if not s:
        return False
    unit = s[-1]
    if unit not in ('C', 'F'):
        return False
    number_part = s[:-1]
    if not number_part or number_part in ('+', '-', '.', '+.', '-.'):
        return False
    if number_part[0] in '+-':
        number_part = number_part[1:]
    if number_part.startswith('.') or number_part.endswith('.'):
        return False
    if number_part.count('.') > 1:
        return False
    try:
        float(number_part)
    except ValueError:
        return False
    return all(ch.isdigit() or ch == '.' for ch in number_part)

def zigzag_convert(s, num_rows):
    n = len(s)
    if num_rows <= 1 or num_rows >= n:
        return s
    cycle = 2 * (num_rows - 1)
    buckets = [[] for _ in range(num_rows)]
    for i, ch in enumerate(s):
        pos = i % cycle
        row = pos if pos < num_rows else cycle - pos
        buckets[row].append(ch)
    return ''.join(''.join(b) for b in buckets)

def count_valleys(lst):
